export default "// util\r\nfunction range(lo, hi) {\r\n\tif (hi == null) {\r\n\t\thi = lo\r\n\t\tlo = 0\r\n\t}\t\r\n\tvar arr = []\r\n\tfor (var i = lo; i < hi; i++) {\r\n\t\tarr.push(i)\r\n\t}\r\n\treturn arr\r\n}\r\nfunction shuffle(array) {\r\n  let currentIndex = array.length,  randomIndex;\r\n\r\n  // While there remain elements to shuffle.\r\n  while (currentIndex > 0) {\r\n  \r\n      // Pick a remaining element.\r\n      randomIndex = Math.floor(Math.random() * currentIndex);\r\n      currentIndex--;\r\n  \r\n      // And swap it with the current element.\r\n      [array[currentIndex], array[randomIndex]] = [\r\n      array[randomIndex], array[currentIndex]];\r\n  }\r\n\r\n  return array;\r\n}\r\nfunction reversed(l) {\r\n\tvar rl = []\r\n\tfor (var i = l.length-1; i >= 0; i--)\r\n\t\trl.push(l[i])\r\n\treturn rl\r\n}\r\n\r\n// constants\r\nconst WIDTH = 30\r\nconst HEIGHT = 30\r\nconst TYPES = ['BLANK', 'NUMBER', 'OPERATOR', 'EQUALS']\r\nconst AXES = ['HORIZONTAL', 'VERTICAL']\r\nconst POSITIONS = ['A', 'B', 'C']\r\nconst DIR = ['UP', 'DOWN', 'LEFT', 'RIGHT']\r\nconst OPERATORS = ['+', '-', '*', '/']\r\n\r\nfunction emptyCell(x,y) {\r\n    return {\r\n        x: x,\r\n        y: y,\r\n        type: 'BLANK',\r\n        axes: {}\r\n    }\r\n}\r\nfunction inGrid(x,y) {\r\n    return x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT\r\n}\r\nfunction cellAt(x,y) {\r\n    if (inGrid(x,y))\r\n        return grid[y][x]\r\n    return emptyCell(x,y)\r\n}\r\n\r\n// create empty grid\r\nvar grid = range(HEIGHT).map(y => {\r\n    return range(WIDTH).map(x => emptyCell(x,y))\r\n})\r\nvar positions = []\r\nrange(HEIGHT).map(y => {\r\n    range(WIDTH).map(x => {\r\n        positions.push({x:x, y:y})\r\n    })\r\n})\r\n        \r\nfunction validAPositionsRelativeToStatement(s) {\r\n    var deltas = []\r\n    if (s.axis == 'HORIZONTAL') {\r\n        deltas = [\r\n            {x:0, y:0},\r\n            {x:2, y:0},\r\n            {x:4, y:0},\r\n            {x:0, y:2},\r\n            {x:2, y:2},\r\n            {x:4, y:2},\r\n            {x:0, y:4},\r\n            {x:2, y:4},\r\n            {x:4, y:4},\r\n        ]\r\n    }\r\n    else if (s.axis == 'VERTICAL') {\r\n        deltas = [\r\n            {x:0, y:0},\r\n            {x:-2, y:0},\r\n            {x:-4, y:0},\r\n            {x:0, y:-2},\r\n            {x:-2, y:-2},\r\n            {x:-4, y:-2},\r\n            {x:0, y:-4},\r\n            {x:-2, y:-4},\r\n            {x:-4, y:-4},\r\n        ]\r\n    }\r\n    return deltas.map(e => {\r\n       return {x: s.aPos.x+e.x, y: s.aPos.y+e.y}\r\n    })\r\n}\r\nfunction verticalStatementsIntersect(sv1, sv2) {\r\n    return sv1.aPos.x == sv2.aPos.x &&\r\n           Math.abs(sv1.aPos.y-sv2.aPos.y) < 5\r\n}\r\nfunction horizontalStatementsIntersect(sh1, sh2) {\r\n    return sh1.aPos.y == sh2.aPos.y &&\r\n           Math.abs(sh1.aPos.x-sh2.aPos.x) < 5\r\n}\r\nfunction makeStatement(aPos,axis) {\r\n    shuffle(OPERATORS)\r\n    var op = OPERATORS[0]\r\n    return {\r\n        aPos: aPos,\r\n        axis: axis,\r\n        a: null,\r\n        b: null,\r\n        c: null,\r\n        op: op\r\n    }\r\n}\r\n\r\n// create topology\r\nvar statements = []\r\nstatements.push(makeStatement({x:10,y:10}, 'HORIZONTAL'))\r\nfor (var i = 0; i < 100000; i++) {\r\n    var valid = true\r\n    \r\n    // pick random statement to branch off\r\n    shuffle(statements)\r\n    for (var g = 0; g < statements.length; g++) {\r\n        var startStatement = statements[g]\r\n        var axis = startStatement.axis == 'HORIZONTAL' ? 'VERTICAL' : 'HORIZONTAL'\r\n        var statement = null\r\n        var validPositionsRelativeToStartStatement = validAPositionsRelativeToStatement(startStatement)\r\n        shuffle(validPositionsRelativeToStartStatement)\r\n        for (var j = 0; j < validPositionsRelativeToStartStatement.length; j++) {\r\n            var aPos = validPositionsRelativeToStartStatement.shift()\r\n            statement = makeStatement(aPos, axis)\r\n        \r\n            // ensure statement doesn't intersect with statements of the same axis\r\n            var statementsOfSameAxis = statements.filter(e => e.axis == axis)\r\n            for (var k = 0; k < statementsOfSameAxis.length; k++) {\r\n                var e = statementsOfSameAxis[k]\r\n                if (axis == 'HORIZONTAL') {\r\n                    if (horizontalStatementsIntersect(e,statement)) {\r\n                        valid = false\r\n                        break\r\n                    }\r\n                }\r\n                else {\r\n                    if (verticalStatementsIntersect(e,statement)) {\r\n                        valid = false\r\n                        break\r\n                    }\r\n                }\r\n            }\r\n    \r\n            // statement intersected in an invalid way\r\n            if (!valid)\r\n                break\r\n        }\r\n\r\n        // statement fits\r\n        if (valid) {\r\n            statements.push(statement)\r\n            break\r\n        }\r\n    }\r\n}\r\n\r\nfunction renderToGrid() {\r\n    for (var i = 0; i < statements.length; i++) {\r\n        var statement = statements[i]\r\n        var aPos = statement.aPos\r\n        var isHorizontal = statement.axis == 'HORIZONTAL'\r\n        var dx = isHorizontal ? 1 : 0\r\n        var dy = isHorizontal ? 0 : -1\r\n        for (var j = 0; j < 5; j++) {\r\n            var x = aPos.x+dx*j\r\n            var y = aPos.y+dy*j\r\n            var cell = cellAt(x,y)\r\n            \r\n            var type = 'BLANK'\r\n            if (j == 0) {\r\n                type = 'NUMBER'\r\n                // cell.num = statement.a\r\n            }\r\n            else if (j == 1) {\r\n                type = 'OPERATOR'\r\n                cell.op = statement.op\r\n            }\r\n            else if (j == 2) {\r\n                type = 'NUMBER'\r\n                // cell.num = statement.b\r\n            }\r\n            else if (j == 3) type = 'EQUALS'\r\n            else if (j == 4) {\r\n                type = 'NUMBER'\r\n                // cell.num = statement.c\r\n            }\r\n            cell.type = type\r\n        }\r\n    }\r\n}\r\nfunction displayNum(num) {\r\n    if (num < 10)\r\n        return ' '+num\r\n    return ''+num\r\n}\r\nfunction toCSV(grid) {\r\n    // util\r\n    const rowIsEmpty = (row) => row.every(cell => cell.type == 'BLANK')\r\n    const transpose = (grid) => grid[0].map((_, colIndex) => grid.map(row => row[colIndex]))\r\n    const trimFront = (grid) => {\r\n        const trimmed = []\r\n        var hitNonEmpty = false\r\n        for (var i = 0; i < grid.length; i++) {\r\n            const row = grid[i]\r\n            const empty = rowIsEmpty(row)\r\n            if (!hitNonEmpty && empty)\r\n                continue\r\n            if (!hitNonEmpty && !empty)\r\n                hitNonEmpty = true\r\n            if (hitNonEmpty)\r\n                trimmed.push(row)\r\n        }\r\n        return trimmed\r\n    }\r\n\r\n    // trim edges\r\n    var trimmedGrid = trimFront(grid)                   // trim left\r\n    trimmedGrid = trimFront(reversed(trimmedGrid))      // trim right\r\n    trimmedGrid = transpose(trimmedGrid)                // rotate\r\n    trimmedGrid = trimFront(trimmedGrid)                // trim left\r\n    trimmedGrid = trimFront(reversed(trimmedGrid))      // trim right\r\n\r\n    // to csv\r\n    var text = reversed(trimmedGrid).map(row => {\r\n        return row.map(cell => {\r\n            if (cell.type == 'NUMBER')\r\n                return cell.num\r\n            else if (cell.type == 'OPERATOR') {\r\n                if (cell.op == '/')\r\n                    return '÷'\r\n                else if (cell.op == '*')\r\n                    return '×'\r\n                return cell.op\r\n            }\r\n            else if (cell.type == 'EQUALS')\r\n                return '='\r\n        }).join(',')\r\n    }).join('\\n')\r\n    return text\r\n}\r\nasync function generate(allDistinct) {\r\n    function getNumberIdent(statement, position) {\r\n        var aPos = statement.aPos\r\n        var isHorizontal = statement.axis == 'HORIZONTAL'\r\n        var dx = isHorizontal ? 1 : 0\r\n        var dy = isHorizontal ? 0 : -1\r\n        var positions = ['a', 'b', 'c']\r\n        var offsets = [0, 2, 4]\r\n        var offset = offsets[positions.indexOf(position)]\r\n        var pos = {x: aPos.x+dx*offset, y: aPos.y+dy*offset}\r\n        return 'N_'+pos.x+'_'+pos.y\r\n    }\r\n\r\n    var allIdents = []\r\n    range(HEIGHT).map(y => {\r\n        range(WIDTH).map(x => {\r\n            var cell = cellAt(x,y)\r\n            if (cell.type == 'NUMBER')\r\n                allIdents.push('N_'+x+'_'+y)\r\n        })\r\n    })\r\n    var predicates = ['plus', 'minus', 'mult', 'div']\r\n    var ops = ['+', '-', '*', '/']\r\n    var prologInput = `Vars = [${allIdents.join(',\\n        ')}],\\n\\n`+\r\n        statements.map(s => {\r\n            var pred = predicates[ops.indexOf(s.op)]\r\n            return `${pred}(${getNumberIdent(s,'a')}, ${getNumberIdent(s,'b')}, ${getNumberIdent(s,'c')})`\r\n        }).join(',\\n')\r\n        + ','\r\n        + (allDistinct ? '\\n\\nall_distinct(Vars),' : '\\n\\n% all_distinct(Vars),')\r\n        + '\\n\\nlabel(Vars).'\r\n\r\n    // set output\r\n    output = prologInput\r\n\r\n    // run prolog\r\n    runProlog(prolog, prologInput, (prologOutput, err) => {\r\n      if (err) {\r\n        async_set('grid', err, true)\r\n        return\r\n      }\r\n      \r\n      const definitions = allIdents.map(ident => {\r\n          const value = prologOutput[ident]\r\n          const identParts = ident.split('_')\r\n          var x = parseInt(identParts[1])\r\n          var y = parseInt(identParts[2])\r\n          return {x:x, y:y, value:value}\r\n      })\r\n\r\n      // update cells with number values\r\n      definitions.map(def => {\r\n          var cell = cellAt(def.x,def.y)\r\n          cell.num = def.value\r\n      })\r\n\r\n      // update grid\r\n      renderToGrid()\r\n\r\n      // set csv\r\n      const lvlcsv = toCSV(grid, 0.5)\r\n      async_set('grid', lvlcsv)\r\n    })\r\n}\r\n\r\n// populate symbols\r\nrenderToGrid()\r\n\r\n// populate numbers\r\nconst allDistinct = true\r\ngenerate(allDistinct)";