const getBorderStyle = ({i, j, imax, jmax, color}) => {
  const border = `1px solid ${color}` 
  const styles = {
    left: {
      borderTop: border,
    },
    right: {
      borderLeft: border,
      borderTop: border,
    },
    top: {
      borderLeft: border,
    },
    bot: {
      borderLeft: border,
      borderTop: border,
    },
    topLeft: {
    },
    topRight: {
      borderLeft: border,
    },
    botLeft: {
      borderTop: border,
    },
    botRight: {
      borderLeft: border,
      borderTop: border,
    },
    center: {
      borderLeft: border,
      borderTop: border,
    },
  }
  const style = (
    i==0 && j==0             ? styles.topLeft  :
    i==imax && j==0          ? styles.topRight :
    i==0 && j==jmax          ? styles.botLeft  :
    i==imax && j==jmax       ? styles.botRight :
    i==0 && j>0 && j<jmax    ? styles.left     :
    i==imax && j>0 && j<jmax ? styles.right    :
    j==0                     ? styles.top      :
    j==jmax                  ? styles.bot      :
                              styles.center
  )
  return style
}

const VTable3 = ({tableData, showHeader, contentClass=''}) => {

  // FIXME
  // if (tableData == null)
  //   return <div style={{height: '600px'}} />

  const {columns, data} = tableData

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    debugTable: false,
  })

  const { rows } = table.getRowModel()

  const tableContainerRef = useRef(null)

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    estimateSize: () => 19,
    getScrollElement: () => tableContainerRef.current,
    measureElement:
      typeof window !== 'undefined' &&
      navigator.userAgent.indexOf('Firefox') === -1
        ? element => element?.getBoundingClientRect().height
        : undefined,
    overscan: 5,
  })

  const imax = columns.length-1
  const jmax = rows.length-1

  return (
    <div
      className={`container ${showHeader ? 'header' : ''} ${contentClass}`}
      ref={tableContainerRef}
      // style={containerStyle}
      // style={style}
    >
      <table style={{ display: 'grid' }}>
        <thead
          style={{
            display: 'grid',
            position: 'sticky',
            top: 0,
            zIndex: 1,
          }}
        >
          {true && (
            table.getHeaderGroups().map(headerGroup => (
              <tr
                key={headerGroup.id}
                style={{ display: 'flex', width: '100%' }}
              >
                {headerGroup.headers.map(header => {
                  const thStyle = {
                    display: 'flex',
                    width: showHeader ? header.getSize() : '16px',
                    marginTop: showHeader ? 0 : `-${header.column.columnDef.size+2}px`,
                  }
                  return (
                    <th
                      key={header.id}
                      style={thStyle}
                    >
                      <div
                        {...{
                          className: header.column.getCanSort()
                            ? 'cursor-pointer select-none'
                            : '',
                          style: {textAlign: 'center', display: 'flex'},
                        }}
                      >
                        <span style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '100%',
                        }}>
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                        </span>
                      </div>
                    </th>
                  )
                })}
              </tr>
            ))
          )}
        </thead>
        <tbody
          style={{
            display: 'grid',
            height: `${rowVirtualizer.getTotalSize()}px`,
            position: 'relative',
          }}
        >
          {rowVirtualizer.getVirtualItems().map(virtualRow => {
            const row = rows[virtualRow.index]
            return (
              <tr
                data-index={virtualRow.index}
                ref={node => rowVirtualizer.measureElement(node)}
                key={row.id}
                style={{
                  display: 'flex',
                  position: 'absolute',
                  transform: `translateY(${virtualRow.start}px)`,
                  width: '100%',
                }}
              >
                {row.getVisibleCells().map(cell => {
                  const style = getBorderStyle({
                    i: cell.column.columnDef.index,
                    j: cell.row.index,
                    imax: imax,
                    jmax: jmax,
                    color: '#acacac',
                  })
                  style.display = 'flex'
                  style.width = cell.column.getSize()
                  if (showHeader)
                    style.minHeight = '19px'
                  else {
                    style.width = '16px'
                    style.height = '16px'
                    style.display = 'inline-block'
                    style.textAlign = 'center'
                    style.verticalAlign = 'middle'
                  }
                  
                  const cellval = cell.getValue()
                  const iscolored = cellval?.celltype == 'colored'
                  var className = cellval === '' ? 'empty' : 'filled'
                  return iscolored ? (
                    <td
                      key={cell.id}
                      style={style}
                      className={cellval.class}
                    >
                      {cellval.val}
                    </td>
                  ) : (
                    <td
                      key={cell.id}
                      style={style}
                      className={className}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </td>
                  )
                })}
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

// code folding
function foldAllRecursive(view, fold) {
  const state = view.state

  // Traverse the syntax tree and collect all foldable ranges
  const foldRanges = []
  syntaxTree(state).iterate({
    enter(node) {
      const isFoldable = foldable(state, node.from, node.to)
      if (isFoldable)
        foldRanges.push({ from: isFoldable.from, to: isFoldable.to });
    }
  })

  // fold or unfold all
  const effect = fold ? foldEffect : unfoldEffect
  view.dispatch({
    effects: foldRanges.map(range => effect.of({ from: range.from, to: range.to }))
  })
}
function unfoldAll(view) {
  foldAllRecursive(view, false)
}
function foldAll(view) {
  foldAllRecursive(view, true)
}
function foldRanges(view, ranges) {
  const state = view.state
  unfoldAll(view)

  // find ranges to fold
  const foldRanges = []
  syntaxTree(state).iterate({
    enter(node) {
      const isFoldable = foldable(state, node.from, node.to)
      if (isFoldable) {
        const inRanges = ranges.some(r => r[0] == isFoldable.from && r[1] == isFoldable.to)
        if (inRanges)
          foldRanges.push({from: isFoldable.from, to: isFoldable.to})
      }
    }
  })

  // fold
  view.dispatch({
    effects: foldRanges.map(r => foldEffect.of({ from: r.from, to: r.to }))
  })
}

